/*
  AD ATTACK-PATH GRAPH — data for ad-map.html

  A directed graph of the Active Directory attack surface. The page draws it
  as a flow diagram (Cytoscape) laid out top-to-bottom by access level, so the
  escalation direction and the chains are visible at a glance.

  MODEL
    meta      title / version / credit
    levels[]  access-level bands, low -> high (used for the ruler + node rank)
    cats[]    categories -> colour (WHAT domain a step belongs to)
    types[]   node kinds -> shape/border (IS this a recon step, an attack,
              a credential-access step, or an objective) — the visual legend
    theory{}  short-key -> { t: title, u: page url } lookup for Theory links
    nodes[]   { id, label, lv(level index), cat, type,
                desc,
                cmds:  [ "example command", ... ],     // 1-2, # comments dim
                variants:[ {label, cmds:[...], note?} ],// optional deeper sub-steps
                attack:["T1557.001", ...],             // MITRE ATT&CK IDs
                prereq:"what you must already hold",    // the "why here" line
                detect:"detection / OPSEC one-liner",
                flag:  "hot" | "danger" | null,         // 🔥 common/quick, 🧨 risky
                th:    "theory-key" | null,             // -> theory{} entry
                tools: [[name, toolkitId|null], ...],   // null = no page yet
                vuln:  [label, vulnId|null] | null,     // null id = no page yet
                kind:  "entry" | "goal" | null,         // entry = a start point
                cve:   "CVE-..." | null }
    edges[]   [sourceId, targetId, label?]              // the attack flow

  Fill a null id later (a new tool/vuln page) and the link lights up
  automatically — no page edits needed.
*/

